// backend/src/lib/signatures/cert.ts
//
// Signing-identity resolution for the cryptographic PDF pipeline.
//
// In production a persistent organisational signing certificate is supplied
// via env (`SIGNING_CERT_P12_BASE64` + `SIGNING_CERT_PASSPHRASE`, generated by
// scripts/generateSigningCert.ts). When absent — local dev, CI, demos — a
// self-signed dev cert is minted lazily and cached per process.
//
// Contract, in order of importance:
//   1. A SET-but-broken env cert is a hard error (`SigningIdentityError`) at
//      resolution — never a silent fallback to the dev identity. index.ts runs
//      `checkSigningIdentityAtBoot()` so this fails the boot, not an
//      envelope-completion request mid-flight.
//   2. Disclosure is derived from the PARSED certificate, not a side-effect
//      flag: mode is "org-self-signed" when the leaf is its own issuer,
//      "ca-issued" otherwise, "dev-ephemeral" for the generated fallback.
//   3. The parsed identity (CN / serial / fingerprint / expiry) feeds the
//      completion certificate and per-envelope attribution columns.

import forge from "node-forge";
import {
    mintSigningIdentity,
    certSha256Fingerprint,
    type MintedIdentity,
} from "./certGen";

/** Passphrase used for the in-process self-signed dev bundle. */
const DEV_PASSPHRASE = "coco-legal-dev";

/** CN shown on the self-signed dev certificate's subject and issuer. */
const DEV_COMMON_NAME = "Coco Legal Signing (dev self-signed)";

/**
 * Signature placeholder size passed to pdflibAddPlaceholder (pdf.ts imports
 * it from here — pdf.ts already depends on this module, so the constant lives
 * on the dependency side of that edge). The PKCS#7 DER must fit in HALF this
 * many bytes (the placeholder is hex-encoded): 16384 → 8 KB of DER, enough for
 * a 4096-bit leaf plus two intermediates. Revisit (32768) only if an RFC-3161
 * timestamp (TSA) is ever added to the CMS.
 */
export const SIGNATURE_PLACEHOLDER_LENGTH = 16384;

/** Days-to-expiry threshold below which the boot check warns. */
const EXPIRY_WARN_DAYS = 90;

export type SigningIdentityMode =
    | "dev-ephemeral"
    | "org-self-signed"
    | "ca-issued";

export interface SigningIdentity {
    mode: SigningIdentityMode;
    subjectCN: string;
    issuerCN: string;
    serialHex: string;
    notBefore: Date;
    notAfter: Date;
    /** Lowercase hex SHA-256 over the leaf certificate DER. */
    sha256Fingerprint: string;
    /** Number of certificates in the P12 (leaf + chain). */
    certificateCount: number;
    /** DER-encoded PKCS#12 handed to P12Signer. */
    p12: Buffer;
    passphrase: string;
}

/** Everything about the identity except the signing material itself. */
export type SigningIdentityDescription = Omit<
    SigningIdentity,
    "p12" | "passphrase"
>;

/** A set-but-unusable SIGNING_CERT_P12_BASE64 / passphrase combination. */
export class SigningIdentityError extends Error {}

let cachedDev: SigningIdentity | undefined;
let cachedEnv:
    | { base64: string; passphrase: string; identity: SigningIdentity }
    | undefined;

function devIdentity(): SigningIdentity {
    if (!cachedDev) {
        const minted: MintedIdentity = mintSigningIdentity({
            commonName: DEV_COMMON_NAME,
            organization: "Coco Legal",
            organizationalUnit: "Document Signing",
            keyBits: 2048,
            validityYears: 10,
            passphrase: DEV_PASSPHRASE,
        });
        cachedDev = {
            mode: "dev-ephemeral",
            subjectCN: minted.subjectCN,
            issuerCN: minted.subjectCN,
            serialHex: minted.serialHex,
            notBefore: minted.notBefore,
            notAfter: minted.notAfter,
            sha256Fingerprint: minted.sha256Fingerprint,
            certificateCount: 1,
            p12: minted.p12,
            passphrase: minted.passphrase,
        };
    }
    return cachedDev;
}

function cnOf(dn: forge.pki.Certificate["subject"]): string {
    return (dn.getField("CN")?.value as string | undefined) ?? "(no CN)";
}

/**
 * Parse an env-supplied P12 into a SigningIdentity, mirroring the constraints
 * @signpdf's P12Signer enforces at signing time (shrouded key bag, RSA key,
 * leaf located by modulus match) so misconfiguration fails HERE, crisply,
 * instead of inside envelope completion.
 */
function parseEnvIdentity(base64: string, passphrase: string): SigningIdentity {
    const compact = base64.replace(/\s+/g, "");
    if (!/^[A-Za-z0-9+/]+=*$/.test(compact) || compact.length === 0) {
        throw new SigningIdentityError(
            "SIGNING_CERT_P12_BASE64 is not valid base64 — re-export the PKCS#12 bundle and paste the base64 string unmodified.",
        );
    }
    const p12 = Buffer.from(compact, "base64");

    let parsed: forge.pkcs12.Pkcs12Pfx;
    try {
        const asn1 = forge.asn1.fromDer(
            forge.util.createBuffer(p12.toString("binary")),
        );
        parsed = forge.pkcs12.pkcs12FromAsn1(asn1, false, passphrase);
    } catch (err) {
        const detail = err instanceof Error ? err.message : String(err);
        const passphraseLikely = /mac|hmac|password|decrypt/i.test(detail);
        throw new SigningIdentityError(
            `SIGNING_CERT_P12_BASE64 could not be opened${
                passphraseLikely
                    ? " — SIGNING_CERT_PASSPHRASE is likely wrong"
                    : " — the bundle does not parse as PKCS#12"
            } (${detail}).`,
        );
    }

    const keyBags = parsed.getBags({
        bagType: forge.pki.oids.pkcs8ShroudedKeyBag,
    })[forge.pki.oids.pkcs8ShroudedKeyBag];
    const key = keyBags?.[0]?.key as forge.pki.rsa.PrivateKey | undefined;
    if (!key) {
        throw new SigningIdentityError(
            "SIGNING_CERT_P12_BASE64 contains no private key — export the P12 WITH the key and a passphrase (P12Signer reads only encrypted key bags).",
        );
    }
    if (!("n" in key) || !key.n) {
        throw new SigningIdentityError(
            "SIGNING_CERT_P12_BASE64 holds a non-RSA key — the PDF signer supports RSA only (ECDSA certificates cannot be used).",
        );
    }

    const certBags =
        parsed.getBags({ bagType: forge.pki.oids.certBag })[
            forge.pki.oids.certBag
        ] ?? [];
    const certs = certBags
        .map((b) => b.cert)
        .filter((c): c is forge.pki.Certificate => Boolean(c));
    const leaf = certs.find((c) => {
        const pub = c.publicKey as forge.pki.rsa.PublicKey;
        return (
            pub?.n && key.n.compareTo(pub.n) === 0 && key.e.compareTo(pub.e) === 0
        );
    });
    if (!leaf) {
        throw new SigningIdentityError(
            "SIGNING_CERT_P12_BASE64 has no certificate matching its private key — the bundle is inconsistent.",
        );
    }

    const now = new Date();
    if (leaf.validity.notAfter.getTime() < now.getTime()) {
        throw new SigningIdentityError(
            `SIGNING_CERT_P12_BASE64 certificate expired ${leaf.validity.notAfter.toISOString()} — envelope completion would produce an invalidly-dated signature. Generate or purchase a replacement.`,
        );
    }
    if (leaf.validity.notBefore.getTime() > now.getTime()) {
        throw new SigningIdentityError(
            `SIGNING_CERT_P12_BASE64 certificate is not valid until ${leaf.validity.notBefore.toISOString()}.`,
        );
    }

    return {
        mode: leaf.isIssuer(leaf) ? "org-self-signed" : "ca-issued",
        subjectCN: cnOf(leaf.subject),
        issuerCN: cnOf(leaf.issuer),
        serialHex: leaf.serialNumber.toLowerCase(),
        notBefore: leaf.validity.notBefore,
        notAfter: leaf.validity.notAfter,
        sha256Fingerprint: certSha256Fingerprint(leaf),
        certificateCount: certs.length,
        p12,
        passphrase,
    };
}

/**
 * Resolve the active signing identity for this process.
 *
 * Env path re-resolves whenever the env values change (cached on the exact
 * strings); the dev fallback is minted lazily at most once per process.
 * Throws `SigningIdentityError` when the env cert is set but unusable.
 */
export function resolveSigningIdentity(): SigningIdentity {
    const base64 = (process.env.SIGNING_CERT_P12_BASE64 ?? "").trim();
    if (base64.length > 0) {
        const passphrase = process.env.SIGNING_CERT_PASSPHRASE ?? "";
        if (
            !cachedEnv ||
            cachedEnv.base64 !== base64 ||
            cachedEnv.passphrase !== passphrase
        ) {
            cachedEnv = {
                base64,
                passphrase,
                identity: parseEnvIdentity(base64, passphrase),
            };
        }
        return cachedEnv.identity;
    }
    return devIdentity();
}

/** The active identity without the signing material (for disclosure/attribution). */
export function describeSigningIdentity(): SigningIdentityDescription {
    const { p12: _p12, passphrase: _pass, ...rest } = resolveSigningIdentity();
    return rest;
}

/**
 * Boot-time check run from index.ts before the server starts listening.
 *
 * - Env cert set but broken → { ok: false } and the caller exits: a
 *   misconfigured identity must fail the deploy, not the first envelope.
 * - Env cert healthy → identity log line + warnings (expiry inside 90 days;
 *   estimated CMS size vs the signature placeholder).
 * - Env unset → dev-ephemeral log line; the identity itself is minted lazily
 *   on first signature, so boot stays fast and tests stay hermetic.
 */
export function checkSigningIdentityAtBoot():
    | { ok: true; logLine: string; warnings: string[] }
    | { ok: false; error: string } {
    const base64 = (process.env.SIGNING_CERT_P12_BASE64 ?? "").trim();
    if (base64.length === 0) {
        return {
            ok: true,
            logLine:
                "[signing] identity: mode=dev-ephemeral (self-signed cert minted on first signature; identity changes every restart)",
            warnings: [],
        };
    }

    let identity: SigningIdentity;
    try {
        identity = resolveSigningIdentity();
    } catch (err) {
        return {
            ok: false,
            error:
                err instanceof Error
                    ? err.message
                    : `SIGNING_CERT_P12_BASE64 is unusable: ${String(err)}`,
        };
    }

    const warnings: string[] = [];
    const daysLeft =
        (identity.notAfter.getTime() - Date.now()) / (24 * 3600 * 1000);
    if (daysLeft < EXPIRY_WARN_DAYS) {
        warnings.push(
            `[signing] certificate expires ${identity.notAfter.toISOString()} (${Math.max(0, Math.floor(daysLeft))} days) — generate or purchase a replacement before then.`,
        );
    }

    // Rough CMS-size check against the signature placeholder: cert chain DER
    // (~p12 size is a safe over-approximation) + signature + attributes.
    const estimatedCmsBytes = identity.p12.length + 1500;
    if (estimatedCmsBytes > SIGNATURE_PLACEHOLDER_LENGTH / 2) {
        warnings.push(
            `[signing] certificate chain (~${identity.p12.length}B) may exceed the ${SIGNATURE_PLACEHOLDER_LENGTH / 2}B signature placeholder — raise SIGNATURE_PLACEHOLDER_LENGTH in lib/signatures/cert.ts.`,
        );
    }

    return {
        ok: true,
        logLine: `[signing] identity: mode=${identity.mode} CN="${identity.subjectCN}" issuer="${identity.issuerCN}" serial=${identity.serialHex} expires=${identity.notAfter.toISOString()} certs=${identity.certificateCount}`,
        warnings,
    };
}
